import{_ as t,H as s,f as a,i as n}from"./chunks/framework.OBtFAaxf.js";const u=JSON.parse('{"title":"How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"how-it-works.md","filePath":"how-it-works.md"}'),o={name:"how-it-works.md"};function i(r,e,c,d,l,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h1><p>datum has five moving parts: a local PGlite database in the browser, a bounding box subscription model, a write outbox sync cycle, IndexedDB persistence for fast reconnect, and automatic reconnection with live status reporting.</p><h2 id="local-first-model" tabindex="-1">Local-first model <a class="header-anchor" href="#local-first-model" aria-label="Permalink to &quot;Local-first model&quot;">​</a></h2><p>When you call <code>DatumClient.connect()</code>, datum boots a full PostgreSQL instance in the browser using <a href="https://pglite.dev" target="_blank" rel="noreferrer">PGlite</a> — a WASM build of Postgres with PostGIS. All <code>query()</code> calls run against this local instance. There is no network round-trip for reads.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// This runs locally — no server involved</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  SELECT * FROM features</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  WHERE ST_Intersects(geom, ST_MakeEnvelope(-122.5, 37.7, -122.4, 37.8, 4326))</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Writes (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>) are captured by an outbox trigger in the local schema and pushed to datum-server asynchronously on a configurable sync cycle (default: every 5 seconds).</p><h2 id="bounding-box-subscriptions" tabindex="-1">Bounding box subscriptions <a class="header-anchor" href="#bounding-box-subscriptions" aria-label="Permalink to &quot;Bounding box subscriptions&quot;">​</a></h2><p>On connect, the client sends a <code>subscribe</code> message declaring a bounding box. datum-server runs a spatial query directly against your PostGIS table and returns only features that intersect the box. This is the initial snapshot.</p><p>From that point on, the server only pushes delta messages to clients whose bounding box intersects the changed feature. A feature updated in San Francisco is never sent to a client subscribed to London. This keeps the wire protocol efficient regardless of total dataset size.</p><h2 id="sync-cycle" tabindex="-1">Sync cycle <a class="header-anchor" href="#sync-cycle" aria-label="Permalink to &quot;Sync cycle&quot;">​</a></h2><p>The full write path:</p><ol><li>Client writes to local PGlite via <code>db.query(&#39;INSERT ...&#39;)</code></li><li>The <code>_datum_capture_change</code> trigger captures the write into <code>_datum_outbox</code> with an auto-incrementing <code>seq</code> column</li><li>Every <code>syncInterval</code> ms (default 5000), the client drains unsynced outbox entries (ordered by <code>seq</code>) and sends a <code>write</code> message to datum-server over WebSocket. Writes already in-flight are skipped.</li><li>datum-server applies each edit directly to PostGIS — last-write-wins on conflict</li><li>datum-server sends an <code>ack</code> back to the originating client with the <code>write_ids</code> that were applied</li><li>The client marks those writes as synced only after receiving the ack; if the connection drops mid-flight the writes are retried on reconnect</li><li>The <code>datum_notify_change</code> trigger fires on the PostGIS table</li><li>datum-server listens for <code>NOTIFY</code> and broadcasts a <code>delta</code> message to all other clients whose bbox intersects the changed feature&#39;s bounding box</li></ol><p>The originating client never receives its own delta back. Delta routing uses the full geometry bounding box, so polygons and lines are correctly broadcast to all overlapping clients — not just those containing the first vertex.</p><h2 id="indexeddb-persistence-and-fast-reconnect" tabindex="-1">IndexedDB persistence and fast reconnect <a class="header-anchor" href="#indexeddb-persistence-and-fast-reconnect" aria-label="Permalink to &quot;IndexedDB persistence and fast reconnect&quot;">​</a></h2><p>On the <strong>first visit</strong>, PGlite boots in-memory, downloads a full snapshot from the server, and writes it to IndexedDB. This takes ~3 seconds.</p><p>On <strong>returning visits</strong>, PGlite loads directly from IndexedDB (~200ms). Local data is immediately queryable. In the background, datum connects to the server and requests only features updated since <code>MAX(updated_at)</code> in the local database — a delta catch-up that runs without blocking the UI.</p><p>A <code>_datum_meta</code> table tracks the schema version. If the client library updates the local schema, it automatically wipes IndexedDB and performs a full re-sync on the next visit.</p><h2 id="connection-status-and-auto-reconnect" tabindex="-1">Connection status and auto-reconnect <a class="header-anchor" href="#connection-status-and-auto-reconnect" aria-label="Permalink to &quot;Connection status and auto-reconnect&quot;">​</a></h2><p>The client exposes a <code>connectionStatus</code> getter (<code>&#39;connecting&#39; | &#39;connected&#39; | &#39;disconnected&#39;</code>) and an <code>onStatusChange</code> callback so your application can react to network changes.</p><p>If the WebSocket drops mid-session, the client automatically reconnects with exponential backoff — 1 s, 2 s, 4 s, … up to 30 s. On reconnect, it sends a subscribe message with <code>since = MAX(updated_at)</code> so only missed deltas are returned; no full re-sync is needed.</p><p>During a disconnected period, local reads and writes continue working normally against PGlite. Pending writes are queued in <code>_datum_outbox</code> and pushed as soon as the connection recovers. You can check how many writes are waiting at any time via <code>client.pendingCount</code> or subscribe to changes with <code>client.onPendingChange(cb)</code>.</p><p>On first connect, <code>connect()</code> rejects with an error after <code>connectTimeout</code> (default 30 s) if the server never responds — rather than hanging forever.</p>`,22)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
